corrected_code:
const busboy = require('busboy');

app.post('/api/devices/models/:modelId/firmware', verifyEngineerAuth, async (req, res) => {
  const { modelId } = req.params;
  const model = await db.query(
    'SELECT id FROM hardware_models WHERE model_id = $1 AND vendor_id = $2',
    [modelId, req.user.vendorId]
  );
  if (model.rowCount === 0) {
    return res.status(403).json({ error: 'Unauthorized: hardware model does not belong to your vendor' });
  }

  const bb = busboy({ headers: req.headers });
  bb.on('file', (name, file, info) => {
    const saveTo = path.join('/srv/firmware_builds', `${modelId}.bin`);
    file.pipe(fs.createWriteStream(saveTo));
  });

  bb.on('close', async () => {
    await db.query('UPDATE hardware_models SET latest_firmware_file = $1 WHERE model_id = $2', [`${modelId}.bin`, modelId]);
    res.json({ message: 'Firmware binary uploaded', modelId });
  });

  req.pipe(bb);
});
